#!/usr/bin/env bash
# Writes pylib/runtime.env: the python-build-standalone release embedding-lib
# bundles, and the SHA256 of its tarball for each machine type, read from the
# release's own SHA256SUMS.
#
#   tools/pin-python.sh <release> <python-version>
#   tools/pin-python.sh 20261026 3.14.10
#
# runtime.env is generated by this script, never edited by hand. Changing the
# bundled Python changes the identity every index records, so the pipeline
# re-embeds after the next release (PLAN §5).
#
# A development tool: not in PAYLOAD, never installed.
set -euo pipefail

HERE="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
REL="${1:?release tag, e.g. 20261026}"
PY="${2:?Python version, e.g. 3.14.10}"
BASE="https://github.com/astral-sh/python-build-standalone/releases/download/$REL"

sums=$(curl -fsSL "$BASE/SHA256SUMS")
sha_for() {
  local f="cpython-$PY+$REL-$1-unknown-linux-gnu-install_only_stripped.tar.gz"
  local s; s=$(printf '%s\n' "$sums" | awk -v f="$f" '$2 == f {print $1}')
  [ -n "$s" ] || { echo "no $f in $BASE/SHA256SUMS" >&2; exit 1; }
  printf '%s' "$s"
}

out="$HERE/pylib/runtime.env"
{
  echo "# Generated by tools/pin-python.sh $REL $PY — do not edit by hand."
  echo "PBS_RELEASE=$REL"
  echo "PY_VERSION=$PY"
  echo "SHA256_x86_64=$(sha_for x86_64)"
  echo "SHA256_aarch64=$(sha_for aarch64)"
} > "$out"
cat "$out"
